import re as _re


def _split_reason_tag(tag, brief=''):
    """将涨停原因拆分为独立概念。
    优先从brief（含+或()格式时拆分），否则用tag。
    格式1: AAA+BBB → [AAA, BBB]
    格式2: AAA(BBB) → [AAA, BBB]
    其他: → [tag]
    """
    source = brief if brief and ('+' in brief or '(' in brief) else (tag or '')
    if not source or source == '未分类':
        return ['未分类']
    if '+' in source:
        parts = [p.strip() for p in source.split('+') if p.strip()]
        if parts:
            return parts
    m = _re.match(r'^(.+?)\((.+?)\)$', source)
    if m:
        return [m.group(1).strip(), m.group(2).strip()]
    return [tag or '未分类']


def _get_sniper_data(lookback=20):
    """
    构建精准狙击数据:
    - dates: [最新→最旧] 交易日列表 (YYYY-MM-DD)
    - data: { date: { reason_tag: [records] } }  (已过滤ST)
    - freq: { date: { tag: count } }  (日期为维度)
    - sorted_tags: [标签名] 按总数降序 (已过滤ST)
    - tag_totals: { tag: total_count }
    - top_tags: [标签名] 用于频度矩阵顶部的Top标签
    """
    if not _kpl_day_files:
        return {'dates': [], 'data': {}, 'freq': {}, 'sorted_tags': [], 'tag_totals': {}, 'top_tags': []}

    # 取最近 lookback 个日期
    trade_dates_set = set()
    for fname in _kpl_day_files:
        d = fname.replace('.json', '')
        trade_dates_set.add(d)

    # 从 _trading_days 中取与 KPL 数据日期交集，再取最近 lookback 个
    all_trade = _trading_days
    if all_trade:
        # 先全部转为 YYYY-MM-DD，过滤出 KPL 有的日期
        recent = []
        for rd in all_trade:
            fmt_date = rd[:4] + '-' + rd[4:6] + '-' + rd[6:8]
            if fmt_date in trade_dates_set:
                recent.append(fmt_date)
        # 取最近 lookback 个
        recent = recent[-lookback:]
    else:
        recent = sorted(trade_dates_set)[-lookback:]

    # 只保留在 KPL 数据中有文件的日期
    valid_dates = [d for d in recent if d in trade_dates_set]
    # 最新在前
    valid_dates.reverse()
    # 取最近10个交易日用于强榜频度排序
    rank_dates = valid_dates[:10]

    # 确保数据已加载
    if valid_dates:
        start = valid_dates[-1].replace('-', '')
        end = valid_dates[0].replace('-', '')
        _kpl_ensure_loaded(start, end)

    # 按 date→reason_tag 分组，过滤ST板块
    data = {}
    freq = {}  # { tag: { date: count } }
    for d in valid_dates:
        day_rows = _kpl_rows_by_date.get(d, [])
        tag_groups = {}
        for r in day_rows:
            tags = _split_reason_tag(r.get('reason_tag', '') or '未分类', r.get('reason_brief', '') or '')
            name = (r.get('stock_name', '') or '').strip()
            if name.startswith('*ST') or name.startswith('ST') or '退' in name:
                continue
            tags = [t for t in tags if not (t.startswith('ST') or t == '退市' or '退' in t)]
            if not tags:
                continue
            for tag in tags:
                tag_groups.setdefault(tag, []).append(r)
        data[d] = tag_groups
        for tag, rows in tag_groups.items():
            freq.setdefault(tag, {})[d] = len(rows)

    # 标签按总频度降序排列
    tag_totals = {}
    for tag, tag_data in freq.items():
        tag_totals[tag] = sum(tag_data.values())
    sorted_tags = sorted(tag_totals.keys(), key=lambda t: -tag_totals[t])

    # 频度矩阵补全缺失日期的0
    for tag in sorted_tags:
        for d in valid_dates:
            if d not in freq.get(tag, {}):
                freq.setdefault(tag, {})[d] = 0

    # 同时构建以标签为维度的频度（前端兼容）: freq = { tag: { date: count } }
    freq_by_tag = {}
    for tag in sorted_tags:
        freq_by_tag[tag] = {}
        for d in valid_dates:
            freq_by_tag[tag][d] = freq.get(tag, {}).get(d, 0)

    # 以日期为维度的频度: freq_by_date = { date: { tag: count } }
    freq_by_date = {}
    for d in valid_dates:
        freq_by_date[d] = {}
        for tag in sorted_tags:
            freq_by_date[d][tag] = freq.get(tag, {}).get(d, 0)

    sorted_tags = [t for t in sorted_tags if t not in SNIPER_EXCLUDE_TAGS]
    # Top标签：取总数前40的标签用于频度矩阵
    top_tags = sorted_tags[:40]

    # 计算近10个交易日的频度用于强榜排序
    rank_tag_totals = {}
    for tag in sorted_tags:
        rank_tag_totals[tag] = sum(freq_by_tag.get(tag, {}).get(d, 0) for d in rank_dates)
    rank_sorted_tags = sorted(rank_tag_totals.keys(), key=lambda t: -rank_tag_totals[t])

    # 强榜标签（按10日频度 >= 10）
    strong_tags_list = [t for t in rank_sorted_tags if rank_tag_totals.get(t, 0) >= 10]

    # 强榜标签近10日逐日明细
    tag_rank_daily = {}
    for tag in rank_sorted_tags:
        tag_rank_daily[tag] = {}
        for d in rank_dates:
            tag_rank_daily[tag][d] = freq_by_tag.get(tag, {}).get(d, 0)

    top_20_strong = []
    # 先建立 code→reason_tag 和 code→reason_brief 映射（最新日期优先）
    code_tag_map = {}
    code_brief_map = {}
    for d in valid_dates:
        for r in _kpl_rows_by_date.get(d, []):
            c = r.get('stock_code', '')
            # valid_dates 最新在前，首次出现即最新日期的标签
            if c and c not in code_tag_map:
                code_tag_map[c] = r.get('reason_tag', '') or '未分类'
                code_brief_map[c] = r.get('reason_brief', '') or ''
    for tag in strong_tags_list:
        tag_stocks = {}  # code -> {code, name, reason_tag, max_lianban, zt_count, latest_date, concepts, reason_brief}
        for d in valid_dates:
            day_records = data.get(d, {}).get(tag, [])
            for r in day_records:
                code = r.get('stock_code', '')
                if not code:
                    continue
                name = r.get('stock_name', '')
                lb = int(r.get('lianban_count', 0) or 0)
                concepts = r.get('concepts', '')
                rb = r.get('reason_brief', '') or ''
                if code not in tag_stocks:
                    tag_stocks[code] = {'code': code, 'name': name, 'reason_tag': tag, 'max_lianban': 0, 'zt_count': 0, 'latest_date': '', 'concepts': concepts, 'reason_brief': rb}
                tag_stocks[code]['max_lianban'] = max(tag_stocks[code]['max_lianban'], lb)
                tag_stocks[code]['zt_count'] += 1
                if d > tag_stocks[code]['latest_date']:
                    tag_stocks[code]['latest_date'] = d
                    tag_stocks[code]['reason_brief'] = rb
                if concepts and not tag_stocks[code]['concepts']:
                    tag_stocks[code]['concepts'] = concepts
        sorted_stocks = sorted(tag_stocks.values(), key=lambda x: (-x['max_lianban'], -x['zt_count']))
        top_20_strong.append({'tag': tag, 'total': rank_tag_totals.get(tag, 0), 'rank_daily': tag_rank_daily.get(tag, {}), 'stocks': sorted_stocks})

    # 获取今日涨停数据，匹配KPL reason_tag，合并到最强梯队中
    today_zt_with_tag = []
    _all_today_stocks = []  # 保存所有akshare原始数据，用于找出未匹配标签的股票
    try:
        import akshare as ak
        import pandas as pd
        today_str = datetime.now().strftime('%Y%m%d')
        df = ak.stock_zt_pool_em(date=today_str)
        if df is not None and not df.empty:
            for _, row in df.iterrows():
                code = str(int(row['代码'])).zfill(6)
                name = row.get('名称', '')
                first_time = int(row['首次封板时间']) if pd.notna(row.get('首次封板时间')) else 999999
                lianban = int(row['连板数']) if pd.notna(row.get('连板数')) else 0
                _all_today_stocks.append({
                    'code': code, 'name': name,
                    'first_time': first_time, 'lianban': lianban
                })
                reason_tag = code_tag_map.get(code, '')
                if reason_tag:
                    today_zt_with_tag.append({
                        'code': code, 'name': name,
                        'first_time': first_time, 'lianban': lianban,
                        'reason_tag': reason_tag
                    })
                else:
                    # O(1) 从 _kpl_rows_by_stock 索引查找最近一次涨停原因标签
                    _found_tag = ''
                    for r in sorted(_kpl_rows_by_stock.get(code, []), key=lambda x: x.get('date', ''), reverse=True):
                        _found_tag = r.get('reason_tag', '') or ''
                        if _found_tag:
                            today_zt_with_tag.append({
                                'code': code, 'name': name,
                                'first_time': first_time, 'lianban': lianban,
                                'reason_tag': _found_tag
                            })
                            code_brief_map[code] = r.get('reason_brief', '') or ''
                            break
                    # 仍未能匹配 → 从全量历史数据(reason_index)中查找最近一次标签
                    if not _found_tag and code in _kpl_stock_latest_tag:
                        _found_tag = _kpl_stock_latest_tag[code]['tag']
                        today_zt_with_tag.append({
                            'code': code, 'name': name,
                            'first_time': first_time, 'lianban': lianban,
                            'reason_tag': _found_tag
                        })
                        code_brief_map[code] = _kpl_stock_latest_tag[code].get('reason_brief', '') or ''
    except Exception:
        pass

    # 将今日涨停合并到对应标签卡片顶部（按拆分后的概念），收集未匹配到Top标签的今日涨停
    tag_to_strong = {item['tag']: item for item in top_20_strong}
    other_today_zt = []
    for zt in today_zt_with_tag:
        tags = _split_reason_tag(zt['reason_tag'] or '', code_brief_map.get(zt['code'], ''))
        matched_any = False
        rb = code_brief_map.get(zt['code'], '')
        for tag in tags:
            if tag in tag_to_strong:
                matched_any = True
                item = tag_to_strong[tag]
                item['stocks'] = [s for s in item['stocks'] if s['code'] != zt['code']]
                # 今日涨停股票的题材从KPL历史数据中获取
                zt_concepts = ''
                if zt['code'] in code_tag_map:
                    for r in sorted(_kpl_rows_by_stock.get(zt['code'], []), key=lambda x: x.get('date', ''), reverse=True):
                        if r.get('concepts', ''):
                            zt_concepts = r.get('concepts', '')
                            break
                insert_entry = {
                    'code': zt['code'], 'name': zt['name'],
                    'max_lianban': zt['lianban'], 'zt_count': 0,
                    'latest_date': today_str[:4]+'-'+today_str[4:6]+'-'+today_str[6:8],
                    'concepts': zt_concepts,
                    'reason_brief': rb,
                    'reason_tag': tag,
                    'is_today_zt': True, 'first_time': zt['first_time'], 'lianban': zt['lianban']
                }
                item['stocks'].insert(0, insert_entry)
        if not matched_any:
            other_today_zt.append({
                'code': zt['code'], 'name': zt['name'],
                'first_time': zt['first_time'], 'lianban': zt['lianban'],
                'reason_tag': zt['reason_tag'], 'reason_brief': rb
            })

    # 将 is_today_zt 传播到所有包含该股票的标签（股票可能在多标签中出现）
    for zt in today_zt_with_tag:
        for item in top_20_strong:
            for s in item['stocks']:
                if s['code'] == zt['code']:
                    s['is_today_zt'] = True
                    s['first_time'] = min(s.get('first_time', 999999), zt.get('first_time', 999999))
                    break

    # 收集完全未匹配标签的今日涨停股票
    untagged_today_zt = []
    matched_codes = set(zt['code'] for zt in today_zt_with_tag)
    for s in _all_today_stocks:
        if s['code'] not in matched_codes:
            untagged_today_zt.append({
                'code': s['code'], 'name': s['name'],
                'first_time': s['first_time'], 'lianban': s['lianban'],
                'reason_tag': '\u672a\u5339\u914d\u6807\u7b7e'
            })

    # 注入今日实时数据到频度分析结构（盘中实时刷新）
    _today_fmt = today_str[:4] + '-' + today_str[4:6] + '-' + today_str[6:8]
    if today_zt_with_tag and _today_fmt not in valid_dates:
        valid_dates.insert(0, _today_fmt)
        # 注入到 data（按拆分后的概念分组）
        today_tag_groups = {}
        for zt in today_zt_with_tag:
            tags = _split_reason_tag(zt['reason_tag'] or '', code_brief_map.get(zt['code'], ''))
            for tag in tags:
                today_tag_groups.setdefault(tag, []).append({
                    'stock_code': zt['code'], 'stock_name': zt['name'],
                    'reason_tag': tag, 'reason_brief': code_brief_map.get(zt['code'], ''),
                    'lianban_count': str(zt['lianban']), 'plate_name': '', 'concepts': ''
                })
        data[_today_fmt] = today_tag_groups
        # 更新频度计数
        for tag, rows_today in today_tag_groups.items():
            freq.setdefault(tag, {})[_today_fmt] = len(rows_today)
            freq_by_tag.setdefault(tag, {})[_today_fmt] = len(rows_today)
            freq_by_date.setdefault(_today_fmt, {})[tag] = len(rows_today)
            tag_totals[tag] = tag_totals.get(tag, 0) + len(rows_today)
        # 补全今日其他标签的0值
        for tag in freq_by_tag:
            if _today_fmt not in freq_by_tag[tag]:
                freq_by_tag[tag][_today_fmt] = 0
                freq_by_date.setdefault(_today_fmt, {})[tag] = 0
        # 重算 sorted_tags 和 top_tags
        sorted_tags = sorted(tag_totals.keys(), key=lambda t: -tag_totals[t])
        sorted_tags = [t for t in sorted_tags if t not in SNIPER_EXCLUDE_TAGS]
        top_tags = sorted_tags[:40]
        # 更新 rank_dates（10个交易日，含今日）
        rank_dates = valid_dates[:10]
        # 重算强榜频度
        rank_tag_totals = {}
        for tag in sorted_tags:
            rank_tag_totals[tag] = sum(freq_by_tag.get(tag, {}).get(d, 0) for d in rank_dates)
        rank_sorted_tags = sorted(rank_tag_totals.keys(), key=lambda t: -rank_tag_totals[t])
        # 重算 tag_rank_daily
        for tag in sorted_tags:
            tag_rank_daily[tag] = {}
            for d in rank_dates:
                tag_rank_daily[tag][d] = freq_by_tag.get(tag, {}).get(d, 0)

    # ===== 风向标 (wind_vane_his_kph) =====
    wind_vane_data = []
    wind_vane_date = ''
    try:
        import levistock as lk
        now_dt = datetime.now()
        today_ymd = now_dt.strftime('%Y-%m-%d')
        wv_finder = StockLinkageFinder()
        # 取上一个交易日
        prev_trade_dates = [d for d in _trading_days if d < today_ymd.replace('-','')]
        wv_date_ymd = ''
        if prev_trade_dates:
            wv_date_ymd = prev_trade_dates[-1]
            wv_date_fmt = wv_date_ymd[:4] + '-' + wv_date_ymd[4:6] + '-' + wv_date_ymd[6:]
            wv_raw = lk.wind_vane_his_kph(wv_date_fmt)
            wind_vane_data = wv_raw
            wind_vane_date = wv_date_fmt
    except Exception:
        wind_vane_data = []

    # ===== 盘面梳理 (get_pmsl) =====
    pmsl_data = []
    pmsl_date = ''
    try:
        import levistock as lk
        now_dt = datetime.now()
        today_fmt = now_dt.strftime('%Y-%m-%d')
        pmsl_raw = lk.get_pmsl(today_fmt, st=500)
        if isinstance(pmsl_raw, dict) and 'List' in pmsl_raw:
            pmsl_data = pmsl_raw['List']
            pmsl_date = today_fmt
    except Exception:
        pmsl_data = []

    # ===== 全量实时数据统计（盘中实时计算每个标签的涨停/上涨/下跌/涨跌幅） =====
    try:
        import levistock as lk
        import hashlib
        # 只获取强榜标签中的非今日涨停股票（分批，每批最多100只）
        _need_codes = []
        seen_codes = set()
        for item in top_20_strong:
            for s in item.get('stocks', []):
                c = s.get('code', '')
                if c and c not in seen_codes:
                    seen_codes.add(c)
                    _need_codes.append(c)
        _rt_cache_key = 'stocks_em_cache_' + hashlib.md5(''.join(_need_codes).encode()).hexdigest()[:16]
        rt_result = _get_cached(_rt_cache_key, ttl=120)
        if rt_result is None and _need_codes:
            rt_result = []
            BATCH = 100
            for i in range(0, len(_need_codes), BATCH):
                batch = _need_codes[i:i+BATCH]
                try:
                    chunk = lk.stocks_em(batch) or []
                    rt_result.extend(chunk)
                except Exception:
                    continue
            _set_cache(_rt_cache_key, rt_result)
        rt_map = {}  # code -> change_pct
        if isinstance(rt_result, list):
            for row in rt_result:
                code = str(row.get('stock_code', '')).zfill(6)
                try:
                    cp = float(row.get('change_pct', 0))
                except (ValueError, TypeError):
                    continue
                if cp is not None:
                    rt_map[code] = cp
        if rt_map:
            def _board_zt_threshold(code):
                """根据股票代码前缀判断涨停阈值"""
                if code.startswith(('300', '301', '688', '689')):
                    return 19.5  # 创业板/科创板 20%
                return 9.9       # 主板 10%
            for item in top_20_strong:
                zt_cnt = 0
                up_cnt = 0
                down_cnt = 0
                total_cp = 0.0
                valid_cnt = 0
                for s in item.get('stocks', []):
                    code = s.get('code', '')
                    if not code or code not in rt_map:
                        s['rt_change'] = None
                        continue
                    cp = rt_map[code]
                    s['rt_change'] = cp  # 每个股票保存实时涨跌幅
                    threshold = _board_zt_threshold(code)
                    if s.get('is_today_zt') or cp >= threshold:
                        zt_cnt += 1
                    elif cp > 0:
                        up_cnt += 1
                    elif cp < 0:
                        down_cnt += 1
                    total_cp += cp
                    valid_cnt += 1
                avg_cp = round(total_cp / valid_cnt, 2) if valid_cnt > 0 else None
                item['rt_stats'] = {
                    'zt': zt_cnt,
                    'up': up_cnt,
                    'down': down_cnt,
                    'avg': avg_cp
                }
    except Exception:
        pass

    return {
        'dates': valid_dates,  # 最新在前
        'rank_dates': rank_dates,  # 近10个交易日
        'data': data,
        'freq': freq_by_tag,  # tag → date → count (前端兼容)
        'freq_by_date': freq_by_date,  # date → tag → count
        'sorted_tags': sorted_tags,
        'tag_totals': tag_totals,
        'rank_tag_totals': rank_tag_totals,  # 10日频度（与强榜一致）
        'top_tags': top_tags,
        'top_20_strong': top_20_strong,
        'today_zt_count': len(today_zt_with_tag) + len(untagged_today_zt),
        'other_today_zt': other_today_zt,
        'untagged_today_zt': untagged_today_zt,
        'wind_vane': wind_vane_data,
        'wind_vane_date': wind_vane_date,
        'pmsl': pmsl_data,
        'pmsl_date': pmsl_date
    }


def _kpl_get_search_text(r):
    """获取KPL记录的可搜索文本字段"""
    return (r.get('stock_name', '') + r.get('stock_code', '') + r.get('plate_name', '')
            + (r.get('reason_tag', '') or '') + (r.get('reason_brief', '') or '') + (r.get('concepts', '') or ''))


def _kpl_get_strict_text(r):
    """严格模式：仅搜索reason_tag字段"""
    return (r.get('reason_tag', '') or '')


def _kpl_is_st(r):
    """判断KPL记录是否为ST股票"""
    name = (r.get('stock_name', '') or '').strip()
    return name.startswith('*ST') or name.startswith('ST') or name.startswith('S') or '退' in name


def _kpl_search_rows(q, strict=False):
    """搜索KPL涨停深挖数据。支持单关键词、OR(|)、AND(&)。
    strict=True时，仅匹配reason_tag字段。"""
    q = q.strip()
    if not q:
        return {'results': [], 'mode': 'single', 'query': q, 'total_hits': 0, 'kw_results': {}, 'keywords': []}
    q_lower = q.lower()
    text_fn = _kpl_get_strict_text if strict else _kpl_get_search_text
    # OR模式
    if '|' in q:
        keywords = [k.strip() for k in q.split('|') if k.strip()]
        if len(keywords) < 2:
            return _kpl_search_rows(keywords[0], strict) if keywords else {'results': [], 'mode': 'single', 'query': q, 'total_hits': 0, 'kw_results': {}, 'keywords': []}
        combined = []
        kw_results = {}
        for kw in keywords:
            kw_lower = kw.lower()
            matched = [r for r in _kpl_rows if kw_lower in text_fn(r).lower()]
            kw_results[kw] = matched
            combined.extend(matched)
        # 去重（同一记录可能在多个关键词中匹配）
        seen = set()
        deduped = []
        for r in combined:
            key = r.get('date', '') + r.get('stock_code', '')
            if key not in seen:
                seen.add(key)
                deduped.append(r)
        return {'results': deduped, 'mode': 'or', 'query': q, 'total_hits': len(deduped), 'kw_results': kw_results, 'keywords': keywords}
    # AND模式
    if '&' in q:
        keywords = [k.strip() for k in q.split('&') if k.strip()]
        if len(keywords) < 2:
            return _kpl_search_rows(keywords[0], strict) if keywords else {'results': [], 'mode': 'single', 'query': q, 'total_hits': 0, 'kw_results': {}, 'keywords': []}
        matched = list(_kpl_rows)
        for kw in keywords:
            kw_lower = kw.lower()
            matched = [r for r in matched if kw_lower in text_fn(r).lower()]
        # 去重（云主机日JSON可能存在重复记录）
        seen = set()
        deduped = []
        for r in matched:
            key = r.get('date', '') + r.get('stock_code', '')
            if key not in seen:
                seen.add(key)
                deduped.append(r)
        return {'results': deduped, 'mode': 'and', 'query': q, 'total_hits': len(deduped), 'kw_results': {}, 'keywords': keywords}
    # 单关键词模式
    matched = [r for r in _kpl_rows if q_lower in text_fn(r).lower()]
    # 去重（云主机日JSON可能存在重复记录）
    seen = set()
    deduped = []
    for r in matched:
        key = r.get('date', '') + r.get('stock_code', '')
        if key not in seen:
            seen.add(key)
            deduped.append(r)
    return {'results': deduped, 'mode': 'single', 'query': q, 'total_hits': len(deduped), 'kw_results': {}, 'keywords': []}


def _kpl_race_match_stock(sc, q_lower, strict):
    """检查股票是否匹配关键词（用于赛马今日涨停检查）。
    strict=True时仅匹配reason_tag。"""
    # 1. 检查_kpl_rows_by_stock中的记录
    records = _kpl_rows_by_stock.get(sc, [])
    for r in records:
        tag = (r.get('reason_tag', '') or '').strip()
        if tag in SNIPER_EXCLUDE_TAGS:
            continue
        if strict:
            search_text = tag
        else:
            search_text = (r.get('stock_name', '') + r.get('stock_code', '')
                           + r.get('plate_name', '') + tag
                           + (r.get('reason_brief', '') or '') + (r.get('concepts', '') or ''))
        if q_lower and q_lower in search_text.lower():
            return True
    # 2. 降级到_kpl_stock_latest_tag
    if sc in _kpl_stock_latest_tag:
        lt = _kpl_stock_latest_tag[sc]
        tag = lt.get('tag', '') or ''
        if tag in SNIPER_EXCLUDE_TAGS:
            return False
        if strict:
            search_text = tag
        else:
            search_text = tag + (lt.get('concepts', '') or '')
        if q_lower and q_lower in search_text.lower():
            return True
    return False


def _kpl_compute_lianban(stock_code, date_str):
    """根据KPL实际数据计算股票在指定日期的连续涨停天数（连板数）。
    date_str: YYYY-MM-DD 格式。"""
    records = _kpl_rows_by_stock.get(stock_code, [])
    if not records:
        return 1
    # 构建该股票的所有涨停日期set (YYYYMMDD格式)
    zt_set = set()
    for r in records:
        d = r.get('date', '').replace('-', '')
        if d:
            zt_set.add(d)
    date_ymd = date_str.replace('-', '')
    if date_ymd not in zt_set:
        return 1
    lb = 1
    curr = date_ymd
    while True:
        prev = finder._get_lagged_date(curr, -1)
        if prev and prev in zt_set:
            lb += 1
            curr = prev
        else:
            break
    return lb


def _kpl_is_restart(stock_code, date_fmt, known_zt=False):
    """判断股票在指定日期是否为'重启'：此前 ≥2 连板、回调数日后再次孤立首板（20个交易日内）。
    规则：当日为该股涨停日且不在连板中（连板中不算重启时刻）；
    从当日向前最多回溯20个交易日，找到最近一次旧的涨停日；
    该旧涨停日属于一条 ≥2 连板的旧链条。
    date_fmt: YYYY-MM-DD
    known_zt: True 表示调用方已确认当日为该股涨停日（盘中注入场景，今日记录可能尚未入库）"""
    if _kpl_compute_lianban(stock_code, date_fmt) >= 2:
        return False  # 正在连板中，不算重启时刻
    records = _kpl_rows_by_stock.get(stock_code, [])
    if not records:
        return False
    zt_set = set()
    for r in records:
        d = r.get('date', '').replace('-', '')
        if d:
            zt_set.add(d)
    date_ymd = date_fmt.replace('-', '')
    if not known_zt and date_ymd not in zt_set:
        return False
    # 从当日向前最多回溯20个交易日，找最近一次旧的涨停日
    cur = date_ymd
    for _ in range(20):
        prev = finder._get_lagged_date(cur, -1)
        if not prev:
            break
        if prev in zt_set:
            # 该旧涨停日属于一条 ≥2 连板的旧链条（继续向前数连续涨停天数）
            chain_len = 1
            pc = prev
            while True:
                pp = finder._get_lagged_date(pc, -1)
                if pp and pp in zt_set:
                    chain_len += 1
                    pc = pp
                else:
                    break
            return chain_len >= 2
        cur = prev
    return False


def _kpl_is_shouban(stock_code, date_str, lookback=15):
    """判断股票在指定日期是否为'首板'（前N个交易日无涨停记录）。
    date_str: YYYY-MM-DD 格式
    lookback: 向前追溯的交易天数（默认15）
    返回值: True=首板（前lookback天无涨停），False=非首板"""
    records = _kpl_rows_by_stock.get(stock_code, [])
    if not records:
        return True  # 无历史记录 => 首板
    date_ymd = date_str.replace('-', '')
    # 计算目标日期之前的 N 个交易日
    td = sorted(_trading_days)
    try:
        idx = td.index(date_ymd)
    except ValueError:
        # date_str 不在交易日列表中，直接查是否有早于该日期的记录
        for r in records:
            rd = r.get('date', '').replace('-', '')
            if rd and rd < date_ymd:
                return False
        return True
    start_idx = max(0, idx - lookback)
    lookback_dates = set(td[start_idx:idx])  # 不含 date_ymd 自身
    for r in records:
        rd = r.get('date', '').replace('-', '')
        if rd and rd in lookback_dates:
            # 该股票在回溯期内有涨停记录
            return False
    return True


def _kpl_filter_lianban(results, lianban_filter):
    """按连板数过滤KPL搜索结果（多选OR逻辑）。
    lianban_filter: 'all' | 'shouban' | '2ban' | '3ban' | '3ban_plus'
    也可用逗号分隔多选，如 'shouban,2ban' 表示首板或2连板
    返回值: 过滤后的结果列表"""
    if not lianban_filter or lianban_filter in (None, 'all', ''):
        return results
    filters = lianban_filter.split(',') if isinstance(lianban_filter, str) else [lianban_filter]
    filtered = []
    for r in results:
        lb = r.get('lianban_computed', 1)
        if isinstance(lb, str):
            try:
                lb = int(lb)
            except (ValueError, TypeError):
                lb = 1
        keep = False
        for f in filters:
            f = f.strip()
            if f == 'shouban' and lb == 1:
                keep = True
                break
            elif f == '2ban' and lb == 2:
                keep = True
                break
            elif f == '3ban' and lb == 3:
                keep = True
                break
            elif f == '3ban_plus' and lb >= 3:
                keep = True
                break
        if keep:
            filtered.append(r)
    return filtered


def _inject_today_zt_to_trajectory(recent_fmt, freq_by_tag, min_lianban=0, stocks_by_tag=None):
    """
    盘中实时补充今日涨停原因标签到轨迹表。
    当今日KPL数据不存在时，从实时涨停池获取今日涨停股票，
    匹配其最近一次KPL标签，注入freq_by_tag。

    Args:
        recent_fmt: 日期列表 (YYYY-MM-DD)
        freq_by_tag: {tag: {date: count}} 会被修改
        min_lianban: 最低连板数过滤（连板版用 >= 2）
        stocks_by_tag: 可选 {tag: {date: [股票明细]}}，传入时额外写入今日注入股票明细

    Returns:
        today_stock_tags: {stock_code: reason_tag}
    """
    today_fmt = datetime.now().strftime('%Y-%m-%d')
    today_ymd = today_fmt.replace('-', '')
    # 检查今日数据是否需要补充：最新日期是今天 且 freq_by_tag中今日无数据
    if recent_fmt[-1] != today_fmt:
        return {}
    has_today_data = any(today_fmt in counts for counts in freq_by_tag.values())
    if has_today_data:
        return {}
    today_stock_tags = {}
    try:
        import akshare as ak
        import pandas as pd
        df = ak.stock_zt_pool_em(date=today_ymd)
        if df is not None and not df.empty:
            for _, row in df.iterrows():
                code = str(int(row['代码'])).zfill(6)
                lianban = int(row['连板数']) if pd.notna(row.get('连板数')) else 0
                # 调用方需要股票明细时，允许"重启首板"(lb<2) 通过连板过滤（盘中补充今日重启）
                is_restart = False
                if stocks_by_tag is not None and lianban < 2:
                    is_restart = _kpl_is_restart(code, today_fmt, known_zt=True)
                if lianban < min_lianban:
                    if not (stocks_by_tag is not None and is_restart):
                        continue
                # LEVEL 1: _kpl_rows_by_stock 最新记录
                reason_tag = ''
                for r in sorted(_kpl_rows_by_stock.get(code, []), key=lambda x: x.get('date', ''), reverse=True):
                    reason_tag = (r.get('reason_tag', '') or '').strip()
                    if reason_tag:
                        break
                # LEVEL 2: _kpl_stock_latest_tag 兜底
                if not reason_tag and code in _kpl_stock_latest_tag:
                    reason_tag = _kpl_stock_latest_tag[code].get('tag', '') or ''
                if reason_tag:
                    today_stock_tags[code] = reason_tag
                    if reason_tag not in freq_by_tag:
                        freq_by_tag[reason_tag] = {}
                    freq_by_tag[reason_tag][today_fmt] = freq_by_tag[reason_tag].get(today_fmt, 0) + 1
                    if stocks_by_tag is not None:
                        name = str(row.get('名称', '')) or ''
                        stocks_by_tag.setdefault(reason_tag, {}).setdefault(today_fmt, []).append({
                            'code': code,
                            'name': name,
                            'lianban': lianban,
                            'is_restart': is_restart,
                            'is_gem': (code[:3] in ('300', '301') or code[:3] in ('688', '689')),
                        })
    except Exception:
        pass
    return today_stock_tags


# ===== 连板总结与预期：明日预期 → 次日实时验证（Session 18） =====
_today_zt_snap_cache = None
_today_zt_snap_ts = 0.0


def _kpl_today_zt_snapshot():
    """盘中 akshare 实时涨停池快照（60s 内存缓存）。返回 {code: {'name':..., 'lianban': int}}。
    非交易时段返回 {}，失败静默返回 {}。"""
    global _today_zt_snap_cache, _today_zt_snap_ts
    now = time.time()
    if _today_zt_snap_cache is not None and now - _today_zt_snap_ts < 60:
        return _today_zt_snap_cache
    _today_zt_snap_cache = {}
    _today_zt_snap_ts = now
    if not _is_trading_hours():
        return _today_zt_snap_cache
    try:
        import akshare as ak
        import pandas as pd
        today_ymd = datetime.now().strftime('%Y%m%d')
        df = ak.stock_zt_pool_em(date=today_ymd)
        if df is not None and not df.empty:
            for _, row in df.iterrows():
                code = str(int(row['代码'])).zfill(6)
                lianban = int(row['连板数']) if pd.notna(row.get('连板数')) else 0
                _today_zt_snap_cache[code] = {
                    'name': str(row.get('名称', '')) or '',
                    'lianban': lianban,
                }
    except Exception:
        _today_zt_snap_cache = {}
    return _today_zt_snap_cache


def _kpl_theme_zt_count(tag, date_fmt):
    """题材某日全量涨停只数（含首板）。优先 _kpl_rows_by_date 按 reason_tag 计数；
    当日无 KPL 且盘中 → 实时涨停池按最新 reason_tag 解析兜底。"""
    rows = _kpl_rows_by_date.get(date_fmt)
    if rows:
        cnt = 0
        for r in rows:
            if (r.get('reason_tag', '') or '').strip() == tag:
                cnt += 1
        return cnt
    snap = _kpl_today_zt_snapshot()
    if not snap:
        return 0
    cnt = 0
    for code, info in snap.items():
        if _kpl_stock_latest_tag.get(code, {}).get('tag', '') == tag:
            cnt += 1
    return cnt


def _kpl_restart_prev_chain(code, date_fmt):
    """重启股断板前的旧连板数：仿 _kpl_is_restart 回溯20交易日内最近旧涨停日，返回该日连板数；无则0。"""
    records = _kpl_rows_by_stock.get(code, [])
    if not records:
        return 0
    zt_set = set()
    for r in records:
        d = r.get('date', '').replace('-', '')
        if d:
            zt_set.add(d)
    date_ymd = date_fmt.replace('-', '')
    cur = date_ymd
    for _ in range(20):
        prev = finder._get_lagged_date(cur, -1)
        if not prev:
            break
        if prev in zt_set:
            return _kpl_compute_lianban(code, f"{prev[:4]}-{prev[4:6]}-{prev[6:]}")
        cur = prev
    return 0


def _kpl_group_expectations(date_fmt, stocks_by_tag):
    """按日期聚合连板+重启题材预期（同题材全部连板+重启并一条）。
    返回 [{tag, stocks, max_lb, top, types}]，按 -max_lb 排序。"""
    by_tag = {}
    for tag, date_map in (stocks_by_tag or {}).items():
        for s in (date_map.get(date_fmt) or []):
            by_tag.setdefault(tag, []).append(s)
    groups = []
    for tag, stocks in by_tag.items():
        lb2 = [s for s in stocks if int(s.get('lianban', 0) or 0) >= 2]
        restart = [s for s in stocks if s.get('is_restart')]
        if not lb2 and not restart:
            continue
        merged = []
        seen = set()
        for s in lb2 + restart:
            c = s.get('code', '') or ''
            if c in seen:
                continue
            seen.add(c)
            merged.append({
                'name': s.get('name', '') or '',
                'code': c,
                'lianban': int(s.get('lianban', 0) or 0),
                'is_restart': bool(s.get('is_restart')),
                'is_gem': bool(s.get('is_gem')),
            })
        if not merged:
            continue
        merged.sort(key=lambda s: (-s['lianban'], s['name']))
        max_lb = max(s['lianban'] for s in merged)
        top = merged[0]
        types = []
        if lb2:
            types.append('ladder')
        if restart:
            types.append('restart')
        groups.append({
            'tag': tag,
            'stocks': merged,
            'max_lb': max_lb,
            'top': {'name': top['name'], 'code': top['code'], 'lianban': top['lianban'],
                    'is_restart': top['is_restart'], 'is_gem': top['is_gem']},
            'types': types,
        })
    groups.sort(key=lambda x: -x['max_lb'])
    return groups


def _kpl_expect_parts(g, date_fmt):
    """确定性生成明日预期结构化分条（前端逐条展示，不挤一行）。
    返回 [{kind:'advance'|'break'|'restart', text:...}, ...]。"""
    parts = []
    if 'ladder' in g['types']:
        top = g['top']
        parts.append({'kind': 'advance',
                      'text': '若晋级%s板 → 题材情绪升温、或推动板块高潮' % (top['lianban'] + 1)})
        parts.append({'kind': 'break',
                      'text': '若断板 → 注意高度退潮'})
    for s in g['stocks']:
        if s.get('is_restart'):
            prev = _kpl_restart_prev_chain(s['code'], date_fmt)
            parts.append({'kind': 'restart',
                          'text': '%s 前期%s连板断板后重启首板：若题材明日走强 → 板块回流机会，关注二波'
                                  % (s['name'], prev)})
    return parts


def _kpl_expect_text(g, date_fmt):
    """确定性生成明日预期整段文本（兼容字段；前端改用 expect_parts 逐条展示）。"""
    return '；'.join(p['text'] for p in _kpl_expect_parts(g, date_fmt))


def _kpl_opportunity_text(verdict):
    """验证 verdict → 机会建议文字（确定性模板）。"""
    if verdict == '晋级成功·板块升温':
        return '龙头晋级，题材情绪升温 → 关注板块低吸/追涨、对应ETF、创业板/科创板套利'
    if verdict == '晋级成功·板块降温':
        return '龙头独立走强、板块降温 → 关注龙头，谨慎跟风，留意补涨'
    if verdict == '断板·板块退潮':
        return '龙头断板、板块退潮 → 注意回避，等待新主线或回流信号'
    if verdict == '断板·板块仍热':
        return '龙头断板但板块仍活跃 → 关注补涨股/新龙头'
    if verdict == '回流确认':
        return '板块回流确认 → 关注二波机会（前期龙头/低位补涨）'
    if verdict == '回流未确认':
        return '回流未确认，继续观察'
    return '连板延续 → 跟踪龙头与板块强度'


def _kpl_build_candidates(tag, prev_date, today_date, verdict, stocks_by_tag):
    """验证后机会候选股：晋级→补涨、断板→反弹关注、回流→回流候选。"""
    cands = []
    seen = set()
    def _add(name, code, role):
        if not code or code in seen:
            return
        seen.add(code)
        cands.append({'name': name, 'code': code, 'role': role})
    today_stocks = (stocks_by_tag or {}).get(tag, {}).get(today_date) or []
    prev_stocks = (stocks_by_tag or {}).get(tag, {}).get(prev_date) or []
    if verdict in ('晋级成功·板块升温', '晋级成功·板块降温'):
        today_max = 0
        for s in today_stocks:
            lb = int(s.get('lianban', 0) or 0)
            if lb > today_max:
                today_max = lb
        for s in today_stocks:
            lb = int(s.get('lianban', 0) or 0)
            if 2 <= lb < today_max:
                _add(s.get('name', ''), s.get('code', ''), '补涨')
        # 今日该题材首板股（KPL；盘中无 KPL 用快照兜底）
        day_rows = _kpl_rows_by_date.get(today_date)
        if day_rows:
            for r in day_rows:
                if (r.get('reason_tag', '') or '').strip() == tag:
                    sc = r.get('stock_code', '') or ''
                    if sc:
                        name = r.get('stock_name', '') or ''
                        if _kpl_compute_lianban(sc, today_date) < 2:
                            _add(name, sc, '补涨')
        else:
            snap = _kpl_today_zt_snapshot()
            for code, info in snap.items():
                if _kpl_stock_latest_tag.get(code, {}).get('tag', '') == tag:
                    if (info.get('lianban', 0) or 0) < 2:
                        _add(info.get('name', ''), code, '补涨')
    elif verdict in ('断板·板块退潮', '断板·板块仍热'):
        for s in prev_stocks:
            if int(s.get('lianban', 0) or 0) >= 2:
                _add(s.get('name', ''), s.get('code', ''), '反弹关注')
    elif verdict in ('回流确认', '回流未确认'):
        for s in today_stocks:
            if s.get('is_restart'):
                _add(s.get('name', ''), s.get('code', ''), '回流候选')
        for s in prev_stocks:
            if int(s.get('lianban', 0) or 0) >= 2:
                _add(s.get('name', ''), s.get('code', ''), '回流候选')
    else:  # 续板观察
        for s in prev_stocks:
            if int(s.get('lianban', 0) or 0) >= 2:
                _add(s.get('name', ''), s.get('code', ''), '龙头跟踪')
    return cands[:10]


def _kpl_verify_expectation(g, prev_date, today_date, stocks_by_tag):
    """验证昨日一条预期：龙头晋级/断板 + 板块热度 + 回流 + 机会建议 + 候选股。"""
    tag = g['tag']
    prev_top = g['top']
    prev_max_lb = g['max_lb']
    code = prev_top['code']
    today_ymd = today_date.replace('-', '')
    snap = _kpl_today_zt_snapshot()
    today_snap_hit = code in snap
    is_zt_today = _kpl_is_zt(code, today_ymd) or today_snap_hit
    if is_zt_today:
        if today_snap_hit:
            new_lb = snap[code]['lianban'] or 1
            if new_lb < 1:
                new_lb = 1
        else:
            new_lb = _kpl_compute_lianban(code, today_date)
        top_status = '晋级' if new_lb > prev_max_lb else '续板'
    else:
        new_lb = 0
        top_status = '断板'
    prev_zt = _kpl_theme_zt_count(tag, prev_date)
    today_zt = _kpl_theme_zt_count(tag, today_date)
    if today_zt > prev_zt:
        heat = 'up'
    elif today_zt < prev_zt:
        heat = 'down'
    else:
        heat = 'flat'
    reflow = ('restart' in g['types']) and (today_zt > prev_zt)
    if 'restart' in g['types']:
        verdict = '回流确认' if reflow else '回流未确认'
    elif top_status == '晋级' and heat == 'up':
        verdict = '晋级成功·板块升温'
    elif top_status == '晋级':
        verdict = '晋级成功·板块降温'
    elif top_status == '断板' and heat == 'down':
        verdict = '断板·板块退潮'
    elif top_status == '断板':
        verdict = '断板·板块仍热'
    else:
        verdict = '续板观察'
    candidates = _kpl_build_candidates(tag, prev_date, today_date, verdict, stocks_by_tag)
    return {
        'tag': tag,
        'prev_max_lb': prev_max_lb,
        'prev_top': {'name': prev_top['name'], 'code': prev_top['code'], 'lianban': prev_top['lianban'],
                     'is_restart': prev_top['is_restart'], 'is_gem': prev_top['is_gem']},
        'top_status': top_status,
        'top_new_lb': new_lb,
        'prev_zt': prev_zt,
        'today_zt': today_zt,
        'heat': heat,
        'reflow': reflow,
        'verdict': verdict,
        'opportunity': _kpl_opportunity_text(verdict),
        'candidates': candidates,
    }


def _build_trajectory_summary(recent_fmt, freq_by_tag, stocks_by_tag):
    """构建连板轨迹的'连板总结与预期'结构化卡片数据。

    数据源：stocks_by_tag（含今日盘中注入）与全局 _kpl_rows_by_date（近10日全量涨停只数）。
    Args:
        recent_fmt: 近N日日期列表 (YYYY-MM-DD, 旧→新)
        freq_by_tag: {tag: {date: count}}（本函数仅用于签名对齐，统计以 stocks_by_tag 为准）
        stocks_by_tag: {tag: {date: [{code,name,lianban,is_restart,is_gem}]}}
    Returns:
        summary dict 或 None（recent_fmt 为空）
    """
    if not recent_fmt:
        return None
    latest_date = recent_fmt[-1]
    # 今日股票聚合：code -> info, tag -> [stock]
    today_stocks = {}
    today_by_tag = {}
    for tag, date_map in (stocks_by_tag or {}).items():
        for s in (date_map.get(latest_date) or []):
            code = s.get('code', '') or ''
            if not code:
                continue
            today_stocks[code] = {
                'code': code,
                'name': s.get('name', '') or '',
                'lianban': int(s.get('lianban', 0) or 0),
                'is_restart': bool(s.get('is_restart')),
                'is_gem': bool(s.get('is_gem')),
                'tag': tag,
            }
            today_by_tag.setdefault(tag, []).append(s)

    def _lb(s):
        return int(s.get('lianban', 0) or 0)

    # 1) 今日连板梯队：lianban>=2 的题材
    today_ladders = []
    for tag, stocks in today_by_tag.items():
        lb2 = [s for s in stocks if _lb(s) >= 2]
        if not lb2:
            continue
        lb2.sort(key=lambda s: (-_lb(s), s.get('name', '') or ''))
        today_ladders.append({
            'tag': tag,
            'top_lianban': max(_lb(s) for s in lb2),
            'stocks': [{'name': s.get('name', '') or '', 'code': s.get('code', '') or '',
                        'lianban': _lb(s), 'is_restart': bool(s.get('is_restart')),
                        'is_gem': bool(s.get('is_gem'))} for s in lb2],
        })
    today_ladders.sort(key=lambda x: -x['top_lianban'])

    # 2) 板块高潮预警：近 N 日内每题材【单日】涨停只数峰值 > 8（历史全量行 + 今日注入，按日去重）
    n = min(10, len(recent_fmt))
    climax_by_tag = {}
    for d_fmt in recent_fmt[-n:]:
        day_sets = {}
        for r in (_kpl_rows_by_date.get(d_fmt) or []):
            tag = (r.get('reason_tag', '') or '').strip()
            sc = r.get('stock_code', '') or ''
            if tag and sc:
                day_sets.setdefault(tag, set()).add(sc)
        for tag, date_map in (stocks_by_tag or {}).items():
            for s in (date_map.get(d_fmt) or []):
                code = s.get('code', '') or ''
                if code:
                    day_sets.setdefault(tag, set()).add(code)
        for tag, codes in day_sets.items():
            cnt = len(codes)
            cur = climax_by_tag.get(tag, {'peak': 0, 'peak_date': ''})
            if cnt > cur['peak']:
                cur['peak'] = cnt
                cur['peak_date'] = d_fmt
            climax_by_tag[tag] = cur
    climax_tags = [{'tag': t, 'days': n, 'peak': v['peak'], 'peak_date': v['peak_date']}
                   for t, v in climax_by_tag.items() if v['peak'] > 8]
    climax_tags.sort(key=lambda x: (-x['peak'], x['tag']))

    # 3) 2连板晋级观察：今日 lianban==2 且非重启
    two_board_tags = []
    for tag, stocks in today_by_tag.items():
        two = [s for s in stocks if _lb(s) == 2 and not s.get('is_restart')]
        if not two:
            continue
        two.sort(key=lambda s: s.get('name', '') or '')
        two_board_tags.append({
            'tag': tag,
            'stocks': [{'name': s.get('name', '') or '', 'code': s.get('code', '') or '',
                        'lianban': _lb(s), 'is_restart': False} for s in two],
        })

    # 4) 重启起2波：今日 is_restart
    restart_tags = []
    for tag, stocks in today_by_tag.items():
        rs = [s for s in stocks if s.get('is_restart')]
        if not rs:
            continue
        rs.sort(key=lambda s: s.get('name', '') or '')
        restart_tags.append({
            'tag': tag,
            'stocks': [{'name': s.get('name', '') or '', 'code': s.get('code', '') or '',
                        'lianban': _lb(s), 'is_restart': True} for s in rs],
        })

    # 5) 今日最高板（lianban>=2）
    highest = None
    for s in today_stocks.values():
        if s['lianban'] >= 2 and (highest is None or s['lianban'] > highest['lianban']):
            highest = {'name': s['name'], 'code': s['code'], 'lianban': s['lianban'], 'tag': s['tag']}

    # 6) 断板预警：昨日有 lianban>=2、今日该题材无 lianban>=2（列出昨日连板股）
    broken_tags = []
    if len(recent_fmt) >= 2:
        prev_date = recent_fmt[-2]
        prev_stocks_by_tag = {}
        for tag, date_map in (stocks_by_tag or {}).items():
            lb2 = [s for s in (date_map.get(prev_date) or []) if _lb(s) >= 2]
            if lb2:
                lb2.sort(key=lambda s: (-_lb(s), s.get('name', '') or ''))
                prev_stocks_by_tag[tag] = lb2
        for tag, stocks in prev_stocks_by_tag.items():
            today_has_lb2 = any(_lb(s) >= 2 for s in (today_by_tag.get(tag) or []))
            if not today_has_lb2:
                broken_tags.append({
                    'tag': tag,
                    'prev_top': max(_lb(s) for s in stocks),
                    'stocks': [{'name': s.get('name', '') or '', 'code': s.get('code', '') or '',
                                'lianban': _lb(s), 'is_restart': bool(s.get('is_restart')),
                                'is_gem': bool(s.get('is_gem'))} for s in stocks],
                })
        broken_tags.sort(key=lambda x: -x['prev_top'])

    # 7) 明日预期（预埋，pending）+ 昨日验证（次日盘中/收盘实时）
    latest_ymd = latest_date.replace('-', '')
    next_ymd = None
    nxt = [d for d in _trading_days if d > latest_ymd]
    if nxt:
        next_ymd = nxt[0]
    next_date = f"{next_ymd[:4]}-{next_ymd[4:6]}-{next_ymd[6:]}" if next_ymd else None
    prev_date = recent_fmt[-2] if len(recent_fmt) >= 2 else None

    expectations = []
    if next_ymd:
        for g in _kpl_group_expectations(latest_date, stocks_by_tag):
            expectations.append({
                'tag': g['tag'],
                'stocks': g['stocks'],
                'max_lb': g['max_lb'],
                'top': g['top'],
                'types': g['types'],
                'next_date': next_date,
                'expect_text': _kpl_expect_text(g, latest_date),
                'expect_parts': _kpl_expect_parts(g, latest_date),
            })

    verification = None
    if prev_date:
        today_has = _kpl_is_zt_date_present(latest_ymd)
        intraday_latest = (latest_date == datetime.now().strftime('%Y-%m-%d')) and _is_trading_hours()
        if today_has or intraday_latest:
            items = []
            for g in _kpl_group_expectations(prev_date, stocks_by_tag):
                items.append(_kpl_verify_expectation(g, prev_date, latest_date, stocks_by_tag))
            verification = {
                'prev_date': prev_date,
                'today_date': latest_date,
                'next_date': next_date,
                'items': items,
            }

    return {
        'latest_date': latest_date,
        'today_ladders': today_ladders,
        'climax_tags': climax_tags,
        'two_board_tags': two_board_tags,
        'restart_tags': restart_tags,
        'highest': highest,
        'broken_tags': broken_tags,
        'today_total': len(today_stocks),
        'today_tags': len(today_by_tag),
        'expectations': expectations,
        'verification': verification,
        'prev_date': prev_date,
        'next_date': next_date,
    }


def _kpl_analyze_rows(q, date_start=None, date_end=None, no_st=None, strict=None, lianban_filter=None):
    """KPL搜索+日期+ST+严格模式+连板过滤"""
    # 先确保数据已加载
    ds = date_start.replace('-', '') if date_start else None
    de = date_end.replace('-', '') if date_end else None
    print(f"[kpl_analyze_rows] q={q} date_start={date_start} date_end={date_end} ds={ds} de={de} no_st={no_st} strict={strict}")
    _kpl_ensure_loaded(ds, de)
    result = _kpl_search_rows(q, strict=(strict == '1'))
    results = result.get('results', [])
    if no_st == '1':
        results = [r for r in results if not _kpl_is_st(r)]
    results = [r for r in results if r.get('reason_tag', '') not in SNIPER_EXCLUDE_TAGS]
    # DEBUG: 过滤前日期范围
    _dates_before = [r.get('date', '') for r in results if r.get('date', '')]
    if _dates_before:
        print(f"[kpl_analyze_rows] BEFORE date_filter: count={len(results)} date_min={min(_dates_before)} date_max={max(_dates_before)}")
    if date_start:
        results = [r for r in results if ((r.get('date', '') or '').replace('-', '')) >= ds]
    if date_end:
        results = [r for r in results if ((r.get('date', '') or '').replace('-', '')) <= de]
    # DEBUG: 过滤后日期范围
    _dates_after = [r.get('date', '') for r in results if r.get('date', '')]
    if _dates_after:
        print(f"[kpl_analyze_rows] AFTER date_filter: count={len(results)} date_min={min(_dates_after)} date_max={max(_dates_after)}")
    # 为每条结果补充正确的连板数（从实际ZT历史计算）
    for r in results:
        sc = r.get('stock_code', '')
        rd = r.get('date', '')
        if sc and rd:
            r['lianban_computed'] = _kpl_compute_lianban(sc, rd)
        else:
            r['lianban_computed'] = 1
    # 连板过滤
    if lianban_filter and lianban_filter != 'all':
        results = _kpl_filter_lianban(results, lianban_filter)
    results.sort(key=lambda x: x.get('date', ''), reverse=True)
    # 同步过滤 kw_results（OR模式多关键词场景）
    _kw = result.get('kw_results', {})
    if _kw:
        _filtered_kw = {}
        for k, v in _kw.items():
            vv = list(v)  # copy
            if no_st == '1':
                vv = [r for r in vv if not _kpl_is_st(r)]
            vv = [r for r in vv if r.get('reason_tag', '') not in SNIPER_EXCLUDE_TAGS]
            if date_start:
                vv = [r for r in vv if ((r.get('date', '') or '').replace('-', '')) >= ds]
            if date_end:
                vv = [r for r in vv if ((r.get('date', '') or '').replace('-', '')) <= de]
            # 连板计算+过滤
            for r in vv:
                sc = r.get('stock_code', '')
                rd = r.get('date', '')
                if sc and rd:
                    r['lianban_computed'] = _kpl_compute_lianban(sc, rd)
                else:
                    r['lianban_computed'] = 1
            if lianban_filter and lianban_filter != 'all':
                vv = _kpl_filter_lianban(vv, lianban_filter)
            vv.sort(key=lambda x: x.get('date', ''), reverse=True)
            _filtered_kw[k] = vv
        result['kw_results'] = _filtered_kw
    result['results'] = results[:500]
    result['total_hits'] = len(results)
    return result


def _kpl_search_cache_key(q, date_start, date_end, no_st, strict, lianban_filter=None):
    import hashlib
    raw = f"kpl_search|{q}|{date_start or ''}|{date_end or ''}|{no_st or ''}|{strict or ''}|{lianban_filter or 'all'}"
    return hashlib.md5(raw.encode('utf-8')).hexdigest()[:16]

def _kpl_search_cache_load(cache_key):
    path = os.path.join(_KPL_SEARCH_CACHE_DIR, f"{cache_key}.json")
    if not os.path.exists(path): return None
    try:
        entry = json.load(open(path, 'r', encoding='utf-8'))
        if entry.get('version', 0) < 6:
            return None
        return entry.get('data')
    except:
        return None

def _kpl_search_cache_save(cache_key, data):
    os.makedirs(_KPL_SEARCH_CACHE_DIR, exist_ok=True)
    path = os.path.join(_KPL_SEARCH_CACHE_DIR, f"{cache_key}.json")
    try:
        json.dump({'data': data, 'timestamp': time.time(), 'version': 6},
                  open(path, 'w', encoding='utf-8'), ensure_ascii=False)
    except Exception as e:
        print(f"[KPL搜索缓存] 写入失败: {e}")

def _kpl_search_cache_clear():
    import glob
    if os.path.isdir(_KPL_SEARCH_CACHE_DIR):
        for f in glob.glob(os.path.join(_KPL_SEARCH_CACHE_DIR, '*.json')):
            try: os.remove(f)
            except: pass

def _kpl_resolve_latest_zt_date(date_end=None):
    """返回全市场连板天梯实际使用的'最新交易日'(YYYYMMDD)"""
    td = getattr(finder, 'trade_dates', None)
    if not td:
        return None
    if date_end:
        de = str(date_end).replace('-', '')
        prev = [d for d in td if d <= de]
        return prev[-1] if prev else None
    return td[-1]


def _kpl_backfill_chain(results, q):
    """连板链条补齐：为命中 2板/3板 的股票，补齐链条上缺失的日期（首板等），
    使涨停节奏/龙头接力能看到完整的 首板→2板→3板 晋级过程。
    只做向后回溯（首板日期早于命中日期），不改动已有记录。
    返回：补齐后的新列表（在原结果基础上追加 _backfilled 条目，按日期降序）。"""
    if not results:
        return results
    # 已存在 (stock_code, YYYYMMDD) 集合，用于判重
    existing = set()
    for r in results:
        sc = r.get('stock_code', '')
        rd = (r.get('date', '') or '').replace('-', '')
        if sc and rd:
            existing.add((sc, rd))
    additions = []
    for r in results:
        sc = r.get('stock_code', '')
        rd = (r.get('date', '') or '').replace('-', '')
        lb = r.get('lianban_computed') or 1
        if not sc or not rd or lb < 2:
            continue
        if r.get('is_strong_rise'):
            continue
        name = r.get('stock_name', '') or ''
        concepts = r.get('concepts', '') or ''
        reason_tag = r.get('reason_tag', '') or q or ''
        reason_brief = r.get('reason_brief', '') or ''
        plate_name = r.get('plate_name', '') or ''
        reason_detail = r.get('reason_detail', '') or ''
        pos = lb          # 命中日连板数 = 链条末端
        curr = rd
        # 从命中日向前补齐链条：curr(N板) → 前一日(N-1板) → … → 首板(1板)
        while pos >= 1 and curr:
            key = (sc, curr)
            if key not in existing:
                d_fmt = f"{curr[:4]}-{curr[4:6]}-{curr[6:]}"
                additions.append({
                    'stock_code': sc,
                    'stock_name': name,
                    'date': d_fmt,
                    'lianban_computed': pos,
                    'reason_tag': reason_tag,
                    'reason_brief': reason_brief,
                    'plate_name': plate_name,
                    'concepts': concepts,
                    'reason_detail': reason_detail,
                    'lianban_desc': '',
                    'change_pct': 0,
                    'is_strong_rise': False,
                    '_backfilled': True,
                })
                existing.add(key)
            curr = finder._get_lagged_date(curr, -1)
            pos -= 1
    if not additions:
        return results
    out = list(results) + additions
    out.sort(key=lambda x: x.get('date', ''), reverse=True)
    return out


def _kpl_full_search(q, date_start, date_end, no_st, strict, gem_extra=True, lianban_filter=None):
    """全量计算KPL搜索，返回完整结果"""
    result = _kpl_analyze_rows(q, date_start, date_end, no_st, strict, lianban_filter)
    if gem_extra:
        result_codes = list(set(r.get('stock_code', '') for r in result.get('results', []) if r.get('stock_code')))
        all_linked = _kpl_get_all_stock_codes_for_keyword(q)
        all_codes = list(set(result_codes + all_linked))
        strong_rise = _kpl_get_gem_strong_rise(all_codes) if all_codes else {}
        if strong_rise:
            new_entries = []
            for code, sr_entries in strong_rise.items():
                latest = _kpl_stock_latest_tag.get(code, {})
                stock_name = latest.get('stock_name', '') or _kpl_stock_index.get(code, {}).get('stock_name', '')
                if not stock_name:
                    continue
                latest_tag = latest.get('tag', '')
                if latest_tag in SNIPER_EXCLUDE_TAGS:
                    continue
                for sr in sr_entries:
                    already_exists = any(
                        r.get('stock_code') == code and r.get('date') == sr['date']
                        for r in result.get('results', [])
                    )
                    if already_exists:
                        continue
                    new_entries.append({
                        'stock_code': code,
                        'stock_name': stock_name,
                        'reason_tag': latest.get('tag', q),
                        'reason_brief': latest.get('reason_brief', ''),
                        'plate_name': latest.get('plate_name', ''),
                        'concepts': latest.get('concepts', ''),
                        'date': sr['date'],
                        'lianban_desc': '',
                        'lianban_computed': 0,
                        'is_strong_rise': True,
                        'change_pct': sr['change_pct'],
                        'reason_detail': latest.get('reason_detail', ''),
                    })
            if new_entries:
                result['results'].extend(new_entries)
                result['results'].sort(key=lambda x: x.get('date', ''), reverse=True)
                result['total_hits'] = len(result['results'])
        result['gem_strong_rise'] = strong_rise

    # 全市场连板天梯 TOP10（基于本地K线DB，不受 zt_data 新鲜度影响），供前端"连板TOP3"展示
    result['top_lianban'] = None
    try:
        de_norm = date_end.replace('-', '') if date_end else None
        ladder = finder.get_lianban_ladder(top_n=10, date_end=de_norm)
        latest = _kpl_resolve_latest_zt_date(date_end=date_end)
        if ladder:
            items = []
            for it in ladder:
                code = it.get('code', '')
                name = it.get('name', '') or ''
                if not name or name == code:
                    name = _kpl_stock_index.get(code, {}).get('stock_name', '') or name or code
                lt = _kpl_stock_latest_tag.get(code, {})
                items.append({
                    'stock_code': code,
                    'stock_name': name,
                    'lianban_computed': int(it.get('consecutive_lianban', 1)),
                    'concepts': '\u3001'.join(it.get('concepts', []) or []),
                    'reason_tag': lt.get('tag', '') or '',
                    'reason_brief': lt.get('reason_brief', '') or '',
                })
            # date 格式化为 YYYY-MM-DD 供前端标题直接显示
            latest_fmt = f"{latest[:4]}-{latest[4:6]}-{latest[6:]}" if latest else ''
            result['top_lianban'] = {'date': latest_fmt, 'items': items}
    except Exception as e:
        print(f"[KPL TOP3] 计算失败: {e}")

    # 搜索窗口内的交易日历(YYYY-MM-DD)，供前端"断板后6个交易日"重启判定
    result['trade_dates'] = []
    try:
        ds = (date_start or '').replace('-', '') or (_trading_days[0] if _trading_days else '')
        de = (date_end or '').replace('-', '') or (_trading_days[-1] if _trading_days else '')
        result['trade_dates'] = [f"{d[:4]}-{d[4:6]}-{d[6:]}" for d in _trading_days if d and ds <= d <= de]
    except Exception as e:
        print(f"[KPL trade_dates] 失败: {e}")

    # 连板链条补齐：为命中2板/3板的股票补齐链条缺失日期（首板等），让涨停节奏/龙头接力看到完整晋级
    try:
        _orig_hits = result.get('total_hits', len(result.get('results', [])))
        result['results'] = _kpl_backfill_chain(result.get('results', []), q)
        _kw = result.get('kw_results')
        if _kw:
            for _k in list(_kw.keys()):
                _kw[_k] = _kpl_backfill_chain(_kw[_k], _k)
        # 命中数保持为关键词匹配数（补齐的链条日不算新命中）
        result['total_hits'] = _orig_hits
    except Exception as e:
        print(f"[KPL 链条补齐] 失败: {e}")
    return result


# ===== 热门题材结构树 =====
def _kpl_resolve_tag(code):
    """涨停标签两级匹配：最新记录 → 全局兜底。返回 (tag, reason_brief)"""
    for r in sorted(_kpl_rows_by_stock.get(code, []), key=lambda x: x.get('date', ''), reverse=True):
        t = (r.get('reason_tag', '') or '').strip()
        if t:
            return t, (r.get('reason_brief', '') or '')
    lt = _kpl_stock_latest_tag.get(code, {})
    return (lt.get('tag', '') or ''), (lt.get('reason_brief', '') or '')


def _kpl_tst_change_pct(codes, trade_date_fmt):
    """批量今日涨幅：levistock 实时 → K线DB 兜底。返回 {code: change_pct}"""
    out = {}
    codes = [c for c in set(codes) if c]
    import levistock as lk
    for i in range(0, len(codes), 100):
        try:
            for row in (lk.stocks_em(codes[i:i+100]) or []):
                code = str(row.get('stock_code', '')).zfill(6)
                try:
                    out[code] = float(row.get('change_pct', 0))
                except (ValueError, TypeError):
                    pass
        except Exception:
            pass
    missing = [c for c in codes if c not in out]
    if missing and trade_date_fmt:
        db = os.path.join(os.path.dirname(os.path.abspath(__file__)), 'data', 'stocks_kline.db')
        try:
            conn = sqlite3.connect(db)
            cur = conn.cursor()
            for i in range(0, len(missing), 500):
                ph = ','.join('?' * len(missing[i:i+500]))
                cur.execute(f"SELECT stock_code, change_pct FROM kline_daily WHERE trade_date=? AND stock_code IN ({ph})",
                            [trade_date_fmt] + missing[i:i+500])
                for c, p in cur.fetchall():
                    try:
                        out[c.zfill(6)] = float(p)
                    except (ValueError, TypeError):
                        pass
            conn.close()
        except Exception:
            pass
    return out


def _kpl_max_chain(all_zt, window_zt):
    """window_zt 内任意日期出发的连续涨停最大段（all_zt 为该股全部涨停日 YYYYMMDD）"""
    if not window_zt:
        return 0
    zset = set(all_zt)
    best = 0
    for d in window_zt:
        n = 1
        c = d
        while True:
            p = finder._get_lagged_date(c, -1)
            if p and p in zset:
                n += 1
                c = p
            else:
                break
        if n > best:
            best = n
    return best


def _build_theme_structure_tree():
    """构建热门题材结构树：
    1) 实时涨停池（akshare，连板≥2为锚点），失败回退 K线DB 连板天梯
    2) 每只连板股定标签（前一日/最近）
    3) 按标签建树：今日梯队(根/连板/首板) + 断板20日 + 近20日 + 近100日
    4) 同分类按今日涨幅降序，每类截断 MAX_STOCKS"""
    _kpl_ensure_loaded()
    MAX_STOCKS = 30
    pool = _get_zt_from_akshare()            # 含 change_pct
    # 最新真实交易日：_trading_days 含预生成的未来日期(至年末)，akshare 池的 trade_date 标签可能指向未来；
    # 统一用 finder 的真实最新交易日(20260731)作为窗口锚点与 date 标签，与 K线DB/KPL数据对齐
    resolved_ymd = _kpl_resolve_latest_zt_date() or ''
    trade_date_fmt = ''
    if resolved_ymd:
        trade_date_fmt = f"{resolved_ymd[:4]}-{resolved_ymd[4:6]}-{resolved_ymd[6:]}"
    elif pool:
        td = pool[0].get('trade_date', '')
        trade_date_fmt = f"{td[:4]}-{td[4:6]}-{td[6:]}" if td else ''
    # 兜底：akshare 失败 → K线DB 连板天梯（finder.get_lianban_ladder 到最新交易日）
    used_ladder_fallback = False
    if not pool:
        used_ladder_fallback = True
        _kpl_ensure_loaded()
        if not resolved_ymd:
            resolved_ymd = _kpl_resolve_latest_zt_date() or ''
        if resolved_ymd:
            trade_date_fmt = f"{resolved_ymd[:4]}-{resolved_ymd[4:6]}-{resolved_ymd[6:]}"
        for it in (finder.get_lianban_ladder(top_n=50) or []):
            code = it.get('code', '')
            name = it.get('name', '') or _kpl_stock_index.get(code, {}).get('stock_name', '') or code
            pool.append({'code': code, 'name': name, 'lianban': int(it.get('consecutive_lianban', 1)),
                         'first_time': 999999, 'zb_count': 0, 'change_pct': 0.0,
                         'concepts': list(it.get('concepts', []) or []), 'concept_count': 0,
                         'trade_date': (trade_date_fmt or '').replace('-', '')})

    # 1) 给每只池内股票定标签 + 分组
    today_by_tag = {}
    for s in pool:
        code = s['code']
        tag, brief = _kpl_resolve_tag(code)
        if not tag:
            tag = '未分类'
        s['reason_tag'] = tag
        s['reason_brief'] = brief
        today_by_tag.setdefault(tag, []).append(s)

    # 1.5) 标签+概念双归属：除主标签树外，按 概念/板块 命中已有题材树（浅拷贝，仅次树带 primary_tag）
    #      蓝色光标(300058)主标签=AI营销，但概念/板块含 AI应用 → 同时归入「AI应用」树今日首板
    qualifying_tags = {tag for tag, stocks in today_by_tag.items()
                       if any(st.get('lianban', 0) >= 2 for st in stocks)}
    for s in pool:
        ptag = s.get('reason_tag', '')
        if not ptag:
            continue
        cands = set()
        for c in (s.get('concepts') or []):                 # akshare 池概念(list)
            c = str(c).strip()
            if c:
                cands.add(c)
        recs = sorted(_kpl_rows_by_stock.get(s['code'], []),
                      key=lambda x: x.get('date', ''), reverse=True)
        latest = recs[0] if recs else None                  # 最新 KPL 记录
        if latest:
            pn = (latest.get('plate_name', '') or '').strip()
            if pn:
                cands.add(pn)
            for sep in ('、', ','):
                for c in (latest.get('concepts', '') or '').split(sep):
                    c = c.strip()
                    if c:
                        cands.add(c)
        for cand in cands:
            if cand == ptag or cand not in qualifying_tags:  # 仅命中已有连板锚点的树
                continue
            lst = today_by_tag.get(cand)
            if lst is None:
                continue
            if any(e.get('code') == s['code'] for e in lst):  # 该树尚无此股
                continue
            s2 = dict(s)
            s2['primary_tag'] = ptag                          # 仅次树标记主标签
            lst.append(s2)

    # 2) 交易日窗口（锚点 = 最新真实交易日）
    today_ymd = resolved_ymd or (pool[0]['trade_date'] if pool else (_trading_days[-1] if _trading_days else ''))
    tds = sorted(_trading_days)
    try:
        ti = tds.index(today_ymd)
    except ValueError:
        ti = len(tds) - 1
    start20 = tds[max(0, ti - 20)]
    start100 = tds[max(0, ti - 100)]
    # 窗口边界保持 YYYYMMDD（与 reason_index/zt_dates 的日期格式一致，避免字符串比较错位）
    s20, s100 = start20, start100

    trees = []
    all_hist_codes = []
    # 第一遍：构建各树梯队与历史叶子（涨幅后统一填充），并收集全部历史代码
    for tag, today_stocks in today_by_tag.items():
        lianban_stocks = [s for s in today_stocks if s.get('lianban', 0) >= 2]
        if not lianban_stocks:
            continue                       # 只展示有连板锚点的题材
        max_lb = max(s['lianban'] for s in today_stocks)
        # 今日梯队
        root = [s for s in today_stocks if s['lianban'] == max_lb]
        tiers = {}
        for b in range(max_lb - 1, 1, -1):
            tiers[b] = [s for s in today_stocks if s['lianban'] == b]
        shouban = [s for s in today_stocks if s['lianban'] <= 1]
        today_codes = set(s['code'] for s in today_stocks)

        # 历史股票（该标签近100日内出现过）
        broken, zt20, zt100 = [], [], []
        hist = _kpl_reason_index.get(tag, []) or []
        by_code = {}
        for r in hist:
            sc = r.get('stock_code', '')
            d = (r.get('date', '') or '').replace('-', '')
            if sc and d and s100 <= d <= today_ymd:
                by_code.setdefault(sc, set()).add(d)
        for sc, tag_dates in by_code.items():
            if sc in today_codes:
                continue
            in20 = any(s20 <= d <= today_ymd for d in tag_dates)
            # 连板史：扫 _kpl_rows_by_stock 该股所有涨停日的最大连续段（窗口内）
            recs = _kpl_rows_by_stock.get(sc, [])
            zt_dates = sorted({(r.get('date', '') or '').replace('-', '') for r in recs})
            wd = [d for d in zt_dates if s20 <= d <= today_ymd]           # 20日窗口
            max_chain20 = _kpl_max_chain(zt_dates, wd)
            name = _kpl_stock_index.get(sc, {}).get('stock_name', '') or (hist[0].get('stock_name', '') if hist else '') or sc
            leaf = {'code': sc, 'name': name, 'lianban': 0, 'change_pct': 0.0,
                    'is_gem': sc[:3] in ('300', '301', '688', '689')}
            if max_chain20 >= 2:
                broken.append(leaf)                       # 断板（近20日历史连板）
            elif in20:
                zt20.append(leaf)                         # 近20日该标签涨停
            else:
                zt100.append(leaf)                        # 近100日同标签（20日外）
        for _l in broken + zt20 + zt100:
            all_hist_codes.append(_l['code'])
        trees.append({
            'tag': tag, 'reason_brief': (lianban_stocks[0].get('reason_brief', '') or ''),
            'max_lianban': max_lb,
            'today_zt_count': len(today_stocks),
            'root': root,
            'tiers': [{'board': b, 'stocks': v} for b, v in sorted(tiers.items(), reverse=True) if v],
            'shouban': shouban,
            'broken': broken, 'zt20': zt20, 'zt100': zt100,
        })

    # 第二遍：全部历史股票涨幅一次批量获取（原 per-tag 多次 levistock 调用 → 单次）
    pct_all = _kpl_tst_change_pct(all_hist_codes, trade_date_fmt)
    # 池内股用池内实时涨幅（历史叶子已排除池内股，二者无交集）
    pct_lookup = dict(pct_all)
    for tag_stocks in today_by_tag.values():
        for s in tag_stocks:
            pct_lookup[s['code']] = s.get('change_pct', 0) or 0

    # 第三遍：涨幅填充 + 排序 + 截断
    def sort_leaves(arr):
        for l in arr:
            l['change_pct'] = round(pct_lookup.get(l['code'], 0), 2)
        arr.sort(key=lambda x: x.get('change_pct', 0), reverse=True)
        return arr[:MAX_STOCKS]
    for t in trees:
        t['root'] = sort_leaves(t['root'])
        t['tiers'] = [{'board': td['board'], 'stocks': sort_leaves(td['stocks'])} for td in t['tiers']]
        t['shouban'] = sort_leaves(t['shouban'])
        t['broken'] = sort_leaves(t['broken'])
        t['zt20'] = sort_leaves(t['zt20'])
        t['zt100'] = sort_leaves(t['zt100'])
    trees.sort(key=lambda t: (-t['max_lianban'], -t['today_zt_count']))
    return {'date': trade_date_fmt, 'fallback': used_ladder_fallback, 'trees': trees}


# ===== 复盘总结和交易计划（题材风向 Section 5）=====
