    html += '<textarea class="ic-textarea" id="icCodeEditor" placeholder="\u8F93\u5165Mermaid\u6D41\u7A0B\u56FE\u4EE3\u7801...\\n\u793A\u4F8B:\\ngraph LR\\n  A[\u4E0A\u6E38] --> B[\u4E2D\u6E38]\\n  B --> C[\u4E0B\u6E38]"></textarea></div>';

