def _get_sina_prefix(code):
    if code.startswith('6') or code.startswith('5'):
        return 'sh'
    return 'sz'


def _limit_pct_for(code, name):
    """计算涨跌幅限制：ST/S 类 5%，创业板(300/301)/科创板(688/689) 20%，主板 10%。"""
    name = (name or '').upper()
    if name and ('ST' in name or name.startswith('S')):
        return 5.0
    if code.startswith('300') or code.startswith('301') or code.startswith('688') or code.startswith('689'):
        return 20.0
    return 10.0


def _spot_quotes_for_codes(codes):
    """实时行情批量获取（30s 内存缓存）。
    Sina 为主源（云主机 IP 被 Sina 403 时自动回退腾讯 qt.gtimg.cn）。
    返回 {code: {'name','price','prev_close','change_pct','limit_pct','limit_up','board'}}。
    非交易时段也返回（前端自行控制轮询）；失败静默跳过。"""
    if not codes:
        return {}
    codes = sorted({c.strip() for c in codes if c.strip()})
    if not codes:
        return {}
    key = 'spot_quotes:' + ','.join(codes)
    cached = _get_cached(key, ttl=30)
    if cached is not None:
        return cached
    import requests as _req
    snap = _kpl_today_zt_snapshot()
    result = {}
    batch_size = 50
    for batch_start in range(0, len(codes), batch_size):
        batch = codes[batch_start:batch_start + batch_size]
        symbols = ','.join([_get_sina_prefix(c) + c for c in batch])
        url = f'https://hq.sinajs.cn/list={symbols}'
        try:
            r = _req.get(url, timeout=15, headers={
                'Referer': 'https://finance.sina.com.cn',
                'User-Agent': 'Mozilla/5.0 (Macintosh; Intel Mac OS X 10_15_7)'
            })
            if r.status_code != 200:
                continue
            for line in r.text.strip().split('\n'):
                line = line.strip()
                if not line or not line.startswith('var hq_str_'):
                    continue
                # 格式: var hq_str_sh600000="name,open,prev_close,current,high,low,..."
                try:
                    content = line[line.index('"') + 1:line.rindex('"')]
                except ValueError:
                    continue
                parts = content.split(',')
                if len(parts) < 4:
                    continue
                scode = line.split('_')[2].split('=')[0]
                raw_code = scode[2:] if len(scode) > 2 else scode
                if raw_code not in codes:
                    continue
                name = parts[0]
                try:
                    prev_close = float(parts[2]) if parts[2] else 0.0
                    current = float(parts[3]) if parts[3] else 0.0
                except (ValueError, IndexError):
                    continue
                if prev_close <= 0:
                    continue
                change_pct = (current - prev_close) / prev_close * 100.0
                limit_pct = _limit_pct_for(raw_code, name)
                board = 'gem' if (raw_code.startswith('300') or raw_code.startswith('301') or
                                  raw_code.startswith('688') or raw_code.startswith('689')) else 'main'
                limit_up = (change_pct >= limit_pct - 0.1) or (raw_code in snap)
                result[raw_code] = {
                    'name': name,
                    'price': round(current, 2),
                    'prev_close': round(prev_close, 2),
                    'change_pct': round(change_pct, 2),
                    'limit_pct': limit_pct,
                    'limit_up': bool(limit_up),
                    'board': board,
                }
        except Exception:
            continue
    # 腾讯回退：Sina 失败/被拦截时补齐缺失代码
    missing = [c for c in codes if c not in result]
    if missing:
        result.update(_tencent_quotes_for_codes(missing, snap))
    _set_cache(key, result)
    return result


def _tencent_quotes_for_codes(codes, snap=None):
    """腾讯实时行情批量获取（qt.gtimg.cn），作为 Sina 403/失败时的回退源。
    返回 {code: {'name','price','prev_close','change_pct','limit_pct','limit_up','board'}}。"""
    if not codes:
        return {}
    import requests as _req
    if snap is None:
        snap = _kpl_today_zt_snapshot()
    result = {}
    batch_size = 50
    for batch_start in range(0, len(codes), batch_size):
        batch = codes[batch_start:batch_start + batch_size]
        symbols = ','.join([_get_sina_prefix(c) + c for c in batch])
        url = f'https://qt.gtimg.cn/q={symbols}'
        try:
            r = _req.get(url, timeout=15, headers={
                'Referer': 'https://gu.qq.com',
                'User-Agent': 'Mozilla/5.0 (Macintosh; Intel Mac OS X 10_15_7)'
            })
            if r.status_code != 200:
                continue
            for line in r.text.strip().split('\n'):
                line = line.strip()
                if not line.startswith('v_'):
                    continue
                try:
                    content = line[line.index('"') + 1:line.rindex('"')]
                except ValueError:
                    continue
                parts = content.split('~')
                if len(parts) < 5:
                    continue
                code = parts[2].strip()
                if not code or code not in codes:
                    continue
                name = parts[1].strip()
                try:
                    current = float(parts[3]) if parts[3] else 0.0
                    prev_close = float(parts[4]) if parts[4] else 0.0
                except (ValueError, IndexError):
                    continue
                if prev_close <= 0:
                    continue
                change_pct = (current - prev_close) / prev_close * 100.0
                limit_pct = _limit_pct_for(code, name)
                board = 'gem' if (code.startswith('300') or code.startswith('301') or
                                  code.startswith('688') or code.startswith('689')) else 'main'
                limit_up = (change_pct >= limit_pct - 0.1) or (code in snap)
                result[code] = {
                    'name': name,
                    'price': round(current, 2),
                    'prev_close': round(prev_close, 2),
                    'change_pct': round(change_pct, 2),
                    'limit_pct': limit_pct,
                    'limit_up': bool(limit_up),
                    'board': board,
                }
        except Exception:
            continue
    return result


def _check_yangbaoyin(spot_data):
    """检测反转：昨天阴线下跌，今天阳线(现价>开盘价)
    使用Sina实时行情，每日快照(data/etf_daily_open.json)保存今日开盘价，
    次日加载昨日开盘价做精确阴线(close<open)检测。
    首次运行（无快照）使用跳空低开回升的代理逻辑。"""
    import requests as _req

    _base_dir = os.path.dirname(os.path.abspath(__file__))
    _snap_path = os.path.join(_base_dir, 'data', 'etf_daily_open.json')
    _today_str = datetime.now().strftime('%Y%m%d')

    # 1. 尝试加载昨日快照（精确阴线检测）
    yesterday_opens = {}
    snap_date = None
    if os.path.exists(_snap_path):
        try:
            with open(_snap_path, 'r') as f:
                snap = json.load(f)
                snap_date = snap.get('date', '')
                if snap_date:
                    yesterday_opens = snap.get('opens', {})
        except Exception:
            pass

    has_snapshot = bool(snap_date and snap_date != _today_str and yesterday_opens)

    # 2. 候选：今日上涨的ETF
    candidates = [item for item in spot_data if item.get('change_pct', 0) > 0]
    candidates.sort(key=lambda x: -x['change_pct'])
    top_candidates = candidates[:200]

    # 3. 分批批量获取Sina实时行情
    sina_map = {}
    batch_size = 50
    for batch_start in range(0, len(top_candidates), batch_size):
        batch = top_candidates[batch_start:batch_start + batch_size]
        symbols = ','.join([_get_sina_prefix(it['code']) + it['code'] for it in batch])
        url = f'https://hq.sinajs.cn/list={symbols}'
        try:
            r = _req.get(url, timeout=15, headers={
                'Referer': 'https://finance.sina.com.cn',
                'User-Agent': 'Mozilla/5.0 (Macintosh; Intel Mac OS X 10_15_7)'
            })
            if r.status_code == 200:
                for line in r.text.strip().split('\n'):
                    line = line.strip()
                    if not line or not line.startswith('var hq_str_'):
                        continue
                    # 格式: var hq_str_sh589720="name,open,prev_close,current,high,low,..."
                    content = line[line.index('"')+1:line.rindex('"')]
                    parts = content.split(',')
                    if len(parts) >= 4:
                        scode = line.split('_')[2].split('=')[0]
                        raw_code = scode[2:] if len(scode) > 2 else scode
                        try:
                            today_open = float(parts[1]) if parts[1] else None
                            prev_close = float(parts[2]) if parts[2] else None
                            current = float(parts[3]) if parts[3] else None
                            if today_open and prev_close and current:
                                sina_map[raw_code] = {
                                    'open': today_open,
                                    'prev_close': prev_close,
                                    'current': current,
                                }
                        except (ValueError, IndexError):
                            pass
        except Exception:
            pass

    # 4. 保存今日开盘价快照（供次日精确检测）
    try:
        today_opens = {}
        for c, s in sina_map.items():
            today_opens[c] = s['open']
        with open(_snap_path, 'w') as f:
            json.dump({'date': _today_str, 'opens': today_opens}, f)
    except Exception:
        pass

    # 5. 检测每个候选
    result = []
    for item in top_candidates:
        code = item['code']
        sina = sina_map.get(code)
        if not sina:
            continue

        today_open = sina['open']
        prev_close = sina['prev_close']
        current = sina['current']

        if has_snapshot and code in yesterday_opens:
            # === 精确检测：使用昨日快照 ===
            yesterday_open = yesterday_opens[code]
            yesterday_close = prev_close
            # 昨天阴线: close < open
            # 今天阳线: current > today_open
            if yesterday_close < yesterday_open and current > today_open:
                result.append({
                    'code': code, 'name': item['name'],
                    'price': item['price'], 'change_pct': item['change_pct'],
                    'category': item['category'], 'subcategory': item['subcategory'],
                    'yesterday_open': yesterday_open,
                    'yesterday_close': yesterday_close,
                    'proxy': False,
                })
        else:
            # === 代理逻辑：跳空低开+回升（快照尚未就绪） ===
            gap_down_pct = (prev_close - today_open) / prev_close * 100 if prev_close > 0 else 0
            if gap_down_pct >= 0.15 and current > today_open and current > prev_close:
                result.append({
                    'code': code, 'name': item['name'],
                    'price': item['price'], 'change_pct': item['change_pct'],
                    'category': item['category'], 'subcategory': item['subcategory'],
                    'yesterday_open': round(prev_close, 4),
                    'yesterday_close': round(today_open, 4),
                    'proxy': True,
                })

    result.sort(key=lambda x: -x['change_pct'])
    return result

def _classify_etf(name):
    for cat, keywords in _ETF_CATEGORIES:
        for kw in keywords:
            if kw in name:
                return cat
    return '其他'
def _cat_order(cat):
    order = {'宽基指数': 0, '行业主题': 1, '商品': 2, '债券': 3, '货币': 4, '跨境': 5}
    return order.get(cat, 6)

def _build_etf_spot():
    """构建 ETF 行情列表（akshare fund_etf_spot_ths）。失败返回 []。供 /api/etf_spot 与复盘ETF匹配复用。"""
    import akshare as ak
    import pandas as pd
    df = ak.fund_etf_spot_ths()
    result = []
    if df is not None and not df.empty:
        for _, row in df.iterrows():
            code = str(row.get('基金代码', '')).strip() if pd.notna(row.get('基金代码')) else ''
            name = str(row.get('基金名称', '')).strip() if pd.notna(row.get('基金名称')) else ''
            price = float(row['当前-单位净值']) if pd.notna(row.get('当前-单位净值')) else None
            change_pct = float(row['增长率']) if pd.notna(row.get('增长率')) else 0.0
            category = _classify_etf(name)
            subcategory = _classify_etf_sub(name, category)
            result.append({
                'code': code, 'name': name, 'price': price,
                'change_pct': change_pct, 'category': category,
                'subcategory': subcategory,
            })
        result.sort(key=lambda x: (_cat_order(x['category']), -x['change_pct']))
    return result

