def _classify_etf_sub(name, category):
    """返回子分类名称"""
    l2_list = _ETF_L2.get(category, [])
    for l2_name, keywords in l2_list:
        if not keywords:
            continue
        for kw in keywords:
            if kw in name:
                return l2_name
    # catch-all
    for l2_name, keywords in l2_list:
        if not keywords:
            return l2_name
    return None


class Handler(BaseHTTPRequestHandler):
    def do_GET(self):
        parsed = urlparse(self.path)
        path = parsed.path
        query = parse_qs(parsed.query)

        # CORS headers
        cors_headers = {
            'Access-Control-Allow-Origin': '*',
        }

        if path == '/' or path == '/index.html':
            self._respond(200, HTML_PAGE.encode('utf-8'), 'text/html; charset=utf-8', cors_headers)

        elif path == '/api/concepts':
            result = finder.get_all_concept_names()
            self._respond_json(result, cors_headers)

        elif path == '/api/today_zt':
            result = _get_cached('today_zt')
            if result is None:
                result = finder.get_today_zt()
                _set_cache('today_zt', result)
            self._respond_json(result, cors_headers)

        elif path == '/api/today_zt_codes':
            result = _get_cached('today_zt_codes')
            if result is None:
                try:
                    import akshare as ak
                    import pandas as pd
                    today_ymd = datetime.now().strftime('%Y%m%d')
                    trade_dates = _trading_days
                    date_str = today_ymd if today_ymd in trade_dates else (trade_dates[-1] if trade_dates else today_ymd)
                    df = ak.stock_zt_pool_em(date=date_str)
                    result = {}
                    if df is not None and not df.empty:
                        for _, row in df.iterrows():
                            code = str(int(row['代码'])).zfill(6)
                            result[code] = {
                                'first_time': int(row['首次封板时间']) if pd.notna(row.get('首次封板时间')) else 999999,
                                'name': str(row['名称']),
                                'lianban': int(row['连板数']) if pd.notna(row.get('连板数')) else 0
                            }
                except Exception:
                    result = {}
                _set_cache('today_zt_codes', result)
            self._respond_json(result, cors_headers)

        elif path == '/api/realtime_zt':
            try:
                result = _get_zt_from_akshare()
                self._respond_json(result or [], cors_headers)
            except Exception as e:
                self._respond_json([], cors_headers)

        elif path == '/api/realtime_prices':
            codes_str = query.get('codes', [''])[0].strip()
            codes = [c.strip() for c in codes_str.split(',') if c.strip()]
            import hashlib
            cache_key = 'rt_prices_' + (hashlib.md5(codes_str.encode()).hexdigest()[:16] if codes_str else 'empty')
            result = _get_cached(cache_key, ttl=120)
            if result is None:
                import levistock as lk
                result = {}
                if codes:
                    BATCH = 100
                    for i in range(0, len(codes), BATCH):
                        batch = codes[i:i+BATCH]
                        try:
                            chunk = lk.stocks_em(batch) or []
                            for row in chunk:
                                code = str(row.get('stock_code', '')).zfill(6)
                                try:
                                    cp = float(row.get('change_pct', 0))
                                    result[code] = cp
                                except (ValueError, TypeError):
                                    continue
                        except Exception:
                            continue
                _set_cache(cache_key, result)
            self._respond_json(result, cors_headers)

        elif path == '/api/spot_quotes':
            codes = [c.strip() for c in query.get('codes', [''])[0].split(',') if c.strip()]
            result = dict(_spot_quotes_for_codes(codes)) if codes else {}
            result['trading'] = _is_trading_hours()
            result['ts'] = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
            self._respond_json(result, cors_headers)

        elif path == '/api/kpl_gem_strong_rise':
            codes_str = query.get('codes', [''])[0].strip()
            codes = [c.strip() for c in codes_str.split(',') if c.strip()]
            lookback = int(query.get('lookback', ['20'])[0])
            import hashlib
            cache_key = 'gem_strong_rise_' + (hashlib.md5((''.join(codes) + str(lookback)).encode()).hexdigest()[:16] if codes else 'gem_strong_rise_empty')
            result = _get_cached(cache_key, ttl=300)
            if result is None:
                result = _kpl_get_gem_strong_rise(codes, lookback=lookback)
                _set_cache(cache_key, result)
            self._respond_json(result, cors_headers)

        elif path == '/api/kpl_active_stocks_20d':
            try:
                lookback = int(query.get('lookback', ['20'])[0])
                cache_key = 'active_stocks_20d'
                result = _get_cached(cache_key, ttl=300)
                if result is None:
                    sniper_data = _get_sniper_data(lookback)
                    limit_up_codes = set()
                    for d, tag_groups in sniper_data.get('data', {}).items():
                        for tag, records in tag_groups.items():
                            for r in records:
                                code = r.get('stock_code', '')
                                if code:
                                    limit_up_codes.add(code)
                    all_codes = list(limit_up_codes)
                    strong_rise = _kpl_get_gem_strong_rise(all_codes, lookback=lookback)
                    strong_rise_codes = set(strong_rise.keys())
                    result = {
                        'limit_up_codes': sorted(limit_up_codes),
                        'strong_rise_codes': sorted(strong_rise_codes)
                    }
                    _set_cache(cache_key, result)
                self._respond_json(result, cors_headers)
            except Exception as e:
                import traceback
                self._respond_json({'error': str(e), 'traceback': traceback.format_exc()}, cors_headers)

        elif path == '/api/recent_trade_dates':
            n = int(query.get('n', ['30'])[0])
            # 合并交易日历 + CSV中有数据的日期，按倒序排列
            trade_dates = set(_trading_days)
            csv_dates = set(_limit_rows_by_date.keys())
            all_dates = sorted(trade_dates | csv_dates, reverse=True)
            recent = all_dates[:n]
            self._respond_json(recent, cors_headers)

        elif path == '/api/history_zt_by_date':
            date_str = query.get('date', [''])[0].strip()
            if not date_str:
                self._respond_json([], cors_headers)
                return
            result = _get_cached('history_zt_' + date_str)
            if result is None:
                rows = _limit_rows_by_date.get(date_str, [])
                if rows:
                    # 从CSV获取
                    seen_codes = {}
                    result = []
                    for r in rows:
                        code = r.get('ts_code', '').replace('.SH','').replace('.SZ','').replace('.BJ','')
                        if code in seen_codes:
                            continue
                        seen_codes[code] = True
                        concepts = finder.get_stock_concepts(code)
                        lianban = _parse_chain_count(r.get('tag', ''))
                        result.append({
                            'code': code,
                            'name': r.get('name', ''),
                            'lianban': lianban,
                            'first_time': 999999,
                            'zb_count': 0,
                            'concepts': list(concepts),
                            'concept_count': len(concepts),
                            'trade_date': date_str,
                        })
                else:
                    # CSV无数据，用akshare实时拉取
                    try:
                        import akshare as ak
                        import pandas as pd
                        df = ak.stock_zt_pool_em(date=date_str)
                        if df is not None and not df.empty:
                            result = []
                            for _, row in df.iterrows():
                                code = str(int(row['代码'])).zfill(6)
                                concepts = finder.get_stock_concepts(code)
                                result.append({
                                    'code': code,
                                    'name': str(row['名称']),
                                    'lianban': int(row['连板数']) if pd.notna(row.get('连板数')) else 0,
                                    'first_time': int(row['首次封板时间']) if pd.notna(row.get('首次封板时间')) else 999999,
                                    'zb_count': int(row['炸板次数']) if pd.notna(row.get('炸板次数')) else 0,
                                    'concepts': list(concepts),
                                    'concept_count': len(concepts),
                                    'trade_date': date_str,
                                })
                            result.sort(key=lambda x: x['first_time'])
                        else:
                            result = []
                    except Exception:
                        result = []
                _set_cache('history_zt_' + date_str, result)
            self._respond_json(result, cors_headers)

        elif path == '/api/zt_word_freq_timeline':
            n = int(query.get('days', ['15'])[0])
            # 获取交易日列表（从finder获取，已含2026年所有交易日）
            trade_dates = _trading_days
            if not trade_dates:
                trade_dates = sorted(_limit_rows_by_date.keys())
            today_ymd = datetime.now().strftime('%Y%m%d')
            valid_dates = [d for d in trade_dates if d <= today_ymd]
            recent_dates = valid_dates[-n:] if len(valid_dates) >= n else valid_dates
            # 预加载KPL题材路径映射 (stock_name → [{l1, l2, l3}])
            kpl_paths_map = _build_kpl_stock_paths_py()
            # 构建 code→name 映射
            code_to_name = {}
            for code, name in getattr(finder, 'stock_name_map', {}).items():
                code_to_name[code] = name
            result = []
            for date_str in reversed(recent_dates):
                cache_key = 'wf_date_' + date_str
                is_today = (date_str == today_ymd)
                cached = _get_cached(cache_key, ttl=3600 if is_today else 14400)
                if cached is not None:
                    result.append(cached)
                    continue
                # 获取该日涨停股票code
                import akshare as ak
                import pandas as pd
                day_codes = set()
                try:
                    df = ak.stock_zt_pool_em(date=date_str)
                    if df is not None and not df.empty:
                        for _, row in df.iterrows():
                            day_codes.add(str(int(row['代码'])).zfill(6))
                except Exception:
                    pass
                if not day_codes:
                    # 回退：用CSV中该日的所有股票
                    for r in _limit_rows_by_date.get(date_str, []):
                        code = r.get('ts_code', '').replace('.SH','').replace('.SZ','').replace('.BJ','')
                        day_codes.add(code)
                # 统计该日涨停股的KPL题材频度（L1/L2/L3分层）
                l1_freq = {}
                l2_freq = {}
                l3_freq = {}
                for code in day_codes:
                    name = code_to_name.get(code, '')
                    if not name:
                        continue
                    paths = kpl_paths_map.get(name, [])
                    for p in paths:
                        l1 = p['l1']
                        l2 = p['l2']
                        l3 = p['l3']
                        l1_freq[l1] = l1_freq.get(l1, 0) + 1
                        l2_freq[l2] = l2_freq.get(l2, 0) + 1
                        l3_freq[l3] = l3_freq.get(l3, 0) + 1
                day_data = {
                    'date': date_str,
                    'l1': [{'tag': t, 'count': c} for t, c in sorted(l1_freq.items(), key=lambda x: -x[1])],
                    'l2': [{'tag': t, 'count': c} for t, c in sorted(l2_freq.items(), key=lambda x: -x[1])],
                    'l3': [{'tag': t, 'count': c} for t, c in sorted(l3_freq.items(), key=lambda x: -x[1])],
                }
                _set_cache(cache_key, day_data)
                result.append(day_data)
            self._respond_json(result, cors_headers)

        elif path == '/api/lianban_ladder':
            result = _get_cached('lianban_ladder')
            if result is None:
                top_n = int(query.get('top_n', ['30'])[0])
                result = finder.get_lianban_ladder(top_n)
                _set_cache('lianban_ladder', result)
            self._respond_json(result, cors_headers)

        elif path == '/api/realtime_ladder':
            result = _get_cached('realtime_ladder', ttl=60)
            if result is None:
                zt_data = _get_zt_from_akshare()
                ladder = [s for s in zt_data if s.get('lianban', 0) >= 2]
                _kpl_ensure_loaded()
                today_ymd = datetime.now().strftime('%Y%m%d')
                prev_trade_dates = [d for d in _trading_days if d < today_ymd]
                prev_date = prev_trade_dates[-1] if prev_trade_dates else ''
                for s in ladder:
                    code = s['code']
                    prev_record = None
                    for r in _kpl_rows_by_stock.get(code, []):
                        _rd = r.get('date', '').replace('-', '')
                        if _rd == prev_date:
                            prev_record = r
                            break
                    if prev_record:
                        s['prev_tag'] = prev_record.get('reason_tag', '') or ''
                        s['prev_brief'] = prev_record.get('reason_brief', '') or ''
                        s['prev_detail'] = prev_record.get('reason_detail', '') or ''
                    elif code in _kpl_stock_latest_tag:
                        lt = _kpl_stock_latest_tag[code]
                        s['prev_tag'] = lt.get('tag', '') or ''
                        s['prev_brief'] = lt.get('reason_brief', '') or ''
                        s['prev_detail'] = lt.get('reason_detail', '') or ''
                    else:
                        s['prev_tag'] = ''
                        s['prev_brief'] = ''
                        s['prev_detail'] = ''
                ladder.sort(key=lambda x: (-x.get('lianban', 0), x.get('first_time', 999999)))
                result = ladder
                _set_cache('realtime_ladder', result)
            self._respond_json(result, cors_headers)

        elif path == '/api/theme_structure_tree':
            no_cache = query.get('no_cache', ['0'])[0].strip() == '1'
            result = None
