                seen = set()
                deduped = []
                for r in kpl_records:
                    k = (r.get('stock_code', ''), (r.get('date', '') or '').replace('-', ''))
                    if k in seen:
                        continue
                    seen.add(k)
                    deduped.append(r)
                kpl_records = deduped
                kpl_records.sort(key=lambda x: x.get('date', ''), reverse=True)
                kpl_concepts_set = set()
